import java.util.Scanner;

public class Main {
    static final int MAXN = 250010;
    static long[] factorial = new long[MAXN];
    static long[] invFactorial = new long[MAXN];
    static long[][] dynamic = new long[30][MAXN];
    static int[] bits = new int[MAXN];
    static long total, limit, modulus;

    static long combination(int a, int b) {
        return factorial[a] * invFactorial[a - b] % modulus * invFactorial[b] % modulus;
    }

    static void addMod(long[] x, int index, long y) {
        x[index] += y;
        if (x[index] >= modulus) x[index] -= modulus;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total = sc.nextLong();
        limit = sc.nextLong();
        modulus = sc.nextLong();

        factorial[0] = 1;
        invFactorial[0] = 1;
        factorial[1] = 1;
        invFactorial[1] = 1;

        for (int i = 2; i <= total; i++) {
            long q = modulus / i;
            long r = modulus - i * q;
            factorial[i] = factorial[i - 1] * i % modulus;
            invFactorial[i] = modulus - q * invFactorial[(int) r] % modulus;
        }
        for (int i = 2; i <= total; i++) {
            invFactorial[i] = invFactorial[i - 1] * invFactorial[i] % modulus;
        }

        long answer = 1;
        for (int i = 1; i <= total; i++) {
            answer = answer * limit % modulus;
        }

        for (int i = 1; i <= total; i++) {
            bits[i] = bits[i >> 1] + (i & 1);
        }

        if ((total & 1) == 1) {
            System.out.println(answer);
            return;
        }

        dynamic[0][0] = 1;
        int maxBits = Math.min(bits[(int) total], (int) limit);

        for (int i = 0; i < maxBits; i++) {
            for (int j = 0; j < total; j++) {
                if (dynamic[i][j] == 0) continue;
                int mask = (int) (total ^ j);
                for (int k = mask; k > j; k = (k - 1) & mask) {
                    int r = k | j;
                    addMod(dynamic, i + 1, (long) dynamic[i][j] * invFactorial[k] % modulus);
                }
            }
        }

        for (int i = 1; i <= limit; i++) {
            long temp = dynamic[i][(int) total] * factorial[(int) limit] % modulus;
            temp = temp * invFactorial[(int) (limit - i)] % modulus;
            temp = temp * factorial[(int) total] % modulus;
            answer -= temp;
        }

        answer = (modulus + answer % modulus) % modulus;
        System.out.println(answer);
        sc.close();
    }
}
